// lifenote/config — wholesale regen (mako-style key=value). Palette roles,
// border styles, opacity and anchor come from the theme; the rest (font, TTF
// path, timeouts, sizes) are reproduced at their current values — per-consumer
// font sizes are not driven by [font].size in M1 (see plan Risk #8).

use crate::theme::{hash, Theme};

pub fn render(t: &Theme) -> String {
    let p = &t.palette;
    let n = &t.lifenote;
    format!(
        "# lifenote — box-drawing-framed notifications. Generated by lifeconf.\n\
         # Edit ~/.config/lifeconf/theme.toml (or run `lifeconf`), not this file.\n\n\
         border-style={border_style}\n\
         critical-border-style={crit_style}\n\n\
         font=/usr/share/fonts/TTF/ShureTechMonoNerdFontMono-Regular.ttf\n\
         font-px=15\n\n\
         background-color={surface}\n\
         background-alpha={alpha}\n\
         text-color={text}\n\
         border-color={border}\n\
         title-color={accent}\n\
         warn-color={warn}\n\
         urgent-color={urgent}\n\n\
         default-timeout=3000\n\
         critical-timeout=0\n\n\
         max-width=40\n\
         max-visible=5\n\
         max-lines=6\n\n\
         anchor={anchor}\n\
         margin=8\n\
         layer=top\n",
        border_style = n.border_style,
        crit_style = n.critical_border_style,
        surface = hash(&p.surface),
        alpha = n.opacity,
        text = hash(&p.text),
        border = hash(&p.border),
        accent = hash(&p.accent),
        warn = hash(&p.warn),
        urgent = hash(&p.urgent),
        anchor = n.position,
    )
}
